/**
 * Real geometry for the two maps, from OpenStreetMap (© OpenStreetMap
 * contributors, ODbL; read 2026-10-09 via Overpass): the coastline stitched
 * into land polygons, the named lakes and rivers, and (farm frame) the roads.
 * Equirectangular with cos(lat0) so shapes keep their proportions; simplified
 * to ~1px at the frame size. `project()` puts a lat/lon onto the same frame,
 * so every pin sits on the same geometry as the coast.
 *
 * Generated by _docs/polarhestar-map-2026-10-09/build_geo.py — do not edit by hand.
 */
export interface GeoFrame {
  width: number
  height: number
  latN: number
  lonW: number
  lat0: number
  k: number
  land: string[]
  islands: string[]
  lakes: Array<[string, string]>
  rivers: Array<[string, string]>
  roads: Array<[string, string]>
}

export const project = (f: GeoFrame, lat: number, lon: number): [number, number] => [
  (lon - f.lonW) * Math.cos((f.lat0 * Math.PI) / 180) * f.k,
  (f.latN - lat) * f.k,
]

